package org.kanger.storage.dumb2;
import java.nio.file.*;
import java.util.*;
import org.kanger.*;
import org.kanger.ContextProductionCapture.*;
import org.kanger.ContextProductionNativeBinding.Entry;
import org.kanger.ContextUniversalFamilyInspection.*;
import org.kanger.enums.StorageLifecycleErrorCode;
import org.kanger.exception.ContextProductionCommitException;

/** Universally quantified conjunctive heads are equivalent for independent and shared binders. */
final class ContextAuthorityQuantifiedConjunction {
    static int checks;static final int WORK=64000000;
    static void require(boolean yes,String why){++checks;if(!yes)throw new AssertionError(why);}
    static final class Expected {
        final Set<Source> locals=new HashSet<>(),donors=new HashSet<>(),bridges=new HashSet<>();final SemanticTermSnapshot x,tailValue,extraValue;Source dt,de;final boolean negative,diagonal;
        Expected(ContextProductionCandidate.Staged a,boolean negative,boolean diagonal,int mode){this.negative=negative;this.diagonal=diagonal;for(Entry e:a.staged.primary)locals.add(e.source);x=a.staged.primary.stream().filter(e->!e.source.equals(a.candidate)).findFirst().get().clauses.get(0).literals.get(0).arguments.get(0).value;SemanticTermSnapshot tv=null,ev=null;
            for(org.kanger.ContextProductionNativeBinding.Snapshot cut:a.foreign)for(Entry e:cut.primary){if(e.clauses.size()==2){Set<String> heads=new HashSet<>();for(Clause c:e.clauses){require(c.literals.size()==2&&c.variables.size()==2,"one whole conjunctive Source has two unary universal clauses");Atom out=c.literals.stream().filter(l->l.predicate.equals("out")).findFirst().get(),head=c.literals.stream().filter(l->!l.predicate.equals("out")).findFirst().get();require(out.arguments.size()==1&&head.arguments.size()==1&&out.positive==negative&&head.positive!=negative&&out.arguments.get(0).variable>=0&&head.arguments.get(0).variable>=0&&out.arguments.get(0).variable!=head.arguments.get(0).variable&&heads.add(head.predicate),"each conjunct retains head-bound variable distinct from input");}require(heads.equals(new HashSet<>(Arrays.asList("tail","extra"))),"both conjuncts belong to one whole primary Bridge Source");bridges.add(e.source);}
                else{require(e.clauses.size()==1&&e.clauses.get(0).literals.size()==1,"donor/Deny unit");Clause c=e.clauses.get(0);Atom atom=c.literals.get(0);if(atom.predicate.equals("q")){require(c.variables.size()==1&&atom.arguments.size()==1&&atom.arguments.get(0).variable>=0&&atom.positive!=negative,"private unary universal donor");donors.add(e.source);}else{require(c.variables.isEmpty()&&atom.arguments.size()==1&&atom.arguments.get(0).variable<0&&atom.positive==negative,"opposite ground Deny");if(atom.predicate.equals("tail")){dt=e.source;tv=atom.arguments.get(0).value;}else{require(atom.predicate.equals("extra"),"known Deny head");de=e.source;ev=atom.arguments.get(0).value;}}}
            }
            tailValue=tv;extraValue=ev;require(locals.size()==2&&locals.contains(a.candidate)&&donors.size()==3&&bridges.size()==2&&donors.stream().map(v->v.context).distinct().count()==3&&bridges.stream().map(v->v.context).distinct().count()==2,"whole X2, independent three donors/two whole Bridges");require((dt!=null)==(mode==1||mode>=3)&&(de!=null)==(mode>=2),"exact private Deny topology");if(mode>=3)require(mode==4?tv.semanticallyEquals(ev):!tv.semanticallyEquals(ev),"same versus off-diagonal native Deny values");if(mode==5)require(!tv.semanticallyEquals(x)&&!ev.semanticallyEquals(x),"both Deny values absent producer premise");
        }
        Set<Source> set(Source... extra){Set<Source> v=new HashSet<>(locals);v.addAll(Arrays.asList(extra));return v;}
        Set<Set<Source>> alternatives(Source extra){Set<Set<Source>> result=new HashSet<>();for(Source q:donors)for(Source b:bridges){Set<Source> v=set(q,b);if(extra!=null)v.add(extra);result.add(v);}return result;}
    }
    static boolean ground(Atom a,SemanticTermSnapshot value){return a.arguments.size()==1&&a.arguments.get(0).variable<0&&a.arguments.get(0).value.semanticallyEquals(value);}
    static boolean counter(Clause c,Expected e){return c.variables.isEmpty()&&c.literals.size()==1&&ground(c.literals.get(0),e.x);}
    static void heads(ContextUniversalUnitRounds.Frontier f,Expected e,int count){Map<String,Set<Set<Source>>> actual=new HashMap<>();actual.put("tail",new HashSet<>());actual.put("extra",new HashSet<>());for(ContextUniversalUnitLedger.Row row:f.products)if(row.clause.literals.size()==1&&actual.containsKey(row.clause.literals.get(0).predicate)){Atom a=row.clause.literals.get(0);require(a.positive!=e.negative&&a.arguments.size()==1&&a.arguments.get(0).variable>=0&&row.clause.variables.size()==1&&row.support.depth==3&&actual.get(a.predicate).add(row.support.sources),"both conjunctive products universal in either binder form, exact depth3/unique support");}for(Set<Set<Source>> routes:actual.values())require(routes.size()==count&&(count==0||routes.equals(e.alternatives(null))),"six identical independently enumerated whole-Source alternatives for each conjunct");}
    static void counterProducts(ContextUniversalUnitRounds.Frontier f,Expected e){Set<Set<Source>> expected=new HashSet<>(),actual=new HashSet<>();for(Source b:e.bridges){if(e.dt!=null)expected.add(e.set(b,e.dt));if(e.de!=null)expected.add(e.set(b,e.de));}int n=0;for(ContextUniversalUnitLedger.Row row:f.products)if(row.clause.literals.size()==1&&row.clause.literals.get(0).predicate.equals("q")){++n;require(counter(row.clause,e)&&row.clause.literals.get(0).positive==e.negative&&row.support.depth==3&&actual.add(row.support.sources),"ground counter-q keeps exact original value, depth3 and independent Deny route");}require(n==expected.size()&&actual.equals(expected),"all Bridge/individual-Deny counteralternatives retained");}
    static void out(ContextUniversalUnitRounds.Frontier f,Expected e){Set<Set<Source>> expected=new HashSet<>(),actual=new HashSet<>();for(Source q:e.donors)expected.add(e.set(q));for(ContextUniversalUnitLedger.Row row:f.products)if(row.clause.literals.size()==1&&row.clause.literals.get(0).predicate.equals("out"))require(row.clause.variables.isEmpty()&&row.clause.literals.get(0).positive!=e.negative&&ground(row.clause.literals.get(0),e.x)&&row.support.depth==2&&actual.add(row.support.sources),"exact original-value out unit and donor support");require(actual.equals(expected),"all three exact unary out alternatives");}
    static void consistent(Result r,Expected e,int mode){require(mode==0&&r.status==Status.CONSISTENT&&r.collision==null&&r.certificate!=null&&r.completedBarriers==3,"both binder forms stabilize without Denies");ContextUniversalFamilyModel.Certificate cert=r.certificate;require(cert.cuts.size()==6&&cert.input.cuts.size()==6,"exact root/three donors/two Bridges");List<ContextUniversalUnitRounds.Receipt> receipts=new ArrayList<>();List<ContextUniversalQuotientModel.Model> models=new ArrayList<>();for(ContextUniversalFamilyModel.Cut cut:cert.cuts){require(cut.receipt.verified&&cut.receipt.input==cert.input&&cut.model.ledger==cut.receipt.closureStep.input,"exact private model/closure binding");receipts.add(cut.receipt);models.add(cut.model);}require(ContextUniversalFamilyModel.certify(cert.input,receipts,models,16,65536,WORK).certified,"independent all-admissible-value model recheck");out(cert.input,e);heads(cert.input,e,6);counterProducts(cert.input,e);require(cert.input.products.size()==39&&cert.input.products.stream().filter(row->row.clause.literals.size()==1).count()==15&&cert.input.products.stream().noneMatch(row->row.clause.literals.size()==1&&row.clause.literals.get(0).predicate.equals("p1")),"exact full39/unit15 frontier, no displaced premise or raw foreign import");}
    static void collision(Result r,Expected e,boolean exactLocal){int routes=(e.dt==null?0:1)+(e.de==null?0:1);require(r.status==Status.COLLISION&&r.certificate==null&&r.completedBarriers==3&&r.collision.oppositions.size()==12*routes,"every selected Deny independently refutes a mandatory universal conjunct");Map<Set<Source>,Set<String>> actual=new HashMap<>();Set<Set<Source>> expected=new HashSet<>();for(Source q:e.donors)for(Source b:e.bridges){if(e.dt!=null)expected.add(new HashSet<>(Arrays.asList(q,b,e.dt)));if(e.de!=null)expected.add(new HashSet<>(Arrays.asList(q,b,e.de)));}for(ContextUniversalUnitProof.Proof p:r.collision.oppositions){require(p.dependsOnX&&p.contradiction&&p.conclusion==null&&p.support.depth==4&&p.leftSupport.depth==0&&p.leftSupport.sources.size()==1&&p.rightSupport.depth==3&&p.rightSupport.sources.size()==4&&p.left.literals.size()==1&&p.right.literals.size()==1,"whole depth4 proof, original private unit versus depth3 product");Set<Source> local=new HashSet<>(),foreign=new HashSet<>();for(Source v:p.support.sources)(v.localX?local:foreign).add(v);require(local.size()==2&&foreign.size()==3&&p.support.sources.size()==5&&expected.contains(foreign),"proof needs exactly one Deny, no unnecessary two-Deny superset");if(exactLocal)require(local.equals(e.locals),"exact fresh local sources");boolean tailRoute=foreign.contains(e.dt);String endpoint=tailRoute?"tail":"extra";Atom l=p.left.literals.get(0),rr=p.right.literals.get(0);require(l.predicate.equals(rr.predicate)&&l.positive!=rr.positive,"opposite same endpoint");if(l.predicate.equals("q"))require(l.positive!=e.negative&&p.left.variables.size()==1&&p.leftSupport.sources.stream().anyMatch(e.donors::contains)&&counter(p.right,e),"ground counter-q preserves original producer dependency");else require(l.predicate.equals(endpoint)&&l.positive==e.negative&&ground(l,tailRoute?e.tailValue:e.extraValue)&&p.leftSupport.sources.contains(tailRoute?e.dt:e.de)&&p.right.variables.size()==1&&rr.arguments.size()==1&&rr.arguments.get(0).variable>=0,"exact private instance refutes universal conjunct for either binder form");require(actual.computeIfAbsent(foreign,k->new HashSet<>()).add(l.predicate),"one proof per route endpoint");}require(actual.keySet().equals(expected),"all donor/whole-Bridge/individual-Deny routes survive");for(Map.Entry<Set<Source>,Set<String>> route:actual.entrySet())require(route.getValue().equals(new HashSet<>(Arrays.asList("q",route.getKey().contains(e.dt)?"tail":"extra"))),"both exact endpoints on every route");}
    static void barriers(ContextProductionCandidate.Staged a,Expected e){ContextUniversalUnitRounds.Frontier initial=ContextUniversalUnitRounds.start(a.staged,a.foreign,WORK);ContextUniversalUnitRounds.Barrier first=ContextUniversalUnitRounds.merge(initial,ContextUniversalAuthorityChain.pass(initial,16),16,WORK);require(first.status==ContextUniversalUnitRounds.Status.MERGED&&first.changed&&initial.products.isEmpty(),"immutable first barrier");out(first.frontier,e);heads(first.frontier,e,0);int saved=first.frontier.products.size();ContextUniversalUnitRounds.Barrier second=ContextUniversalUnitRounds.merge(first.frontier,ContextUniversalAuthorityChain.pass(first.frontier,16),16,WORK);require(second.status==ContextUniversalUnitRounds.Status.MERGED&&second.changed&&first.frontier.products.size()==saved,"immutable second barrier");out(second.frontier,e);heads(second.frontier,e,6);counterProducts(second.frontier,e);require(second.frontier.products.stream().filter(row->row.clause.literals.size()==1).count()==15+2*((e.dt==null?0:1)+(e.de==null?0:1)),"second barrier exports both universal conjuncts and all exact counter-q routes");}
    static ContextUniversalCandidate.Evaluation inspect(ContextSevenPremiseNativeWriteRunner.Fixture f,String text,int rounds)throws Exception{return f.db.qualifyUniversalProductionCandidate(f.root,text,1000,rounds,16,16,65536,1000000,WORK,500000,WORK);}
    static void one(boolean negative,boolean reverse,boolean diagonal,int mode,boolean nativePath)throws Exception{
        Path dir=Files.createTempDirectory("quantified-conjunction-");System.setProperty("user.home",dir.toString());String sign=negative?"~":"";List<String> names=new ArrayList<>();
        for(String name:new String[]{"A1","A2","A3"}){ContextAuthorityChain.create(dir,name,"!@x "+sign+"q(x);");names.add(name);}for(String name:new String[]{"Bridge1","Bridge2"}){ContextAuthorityChain.create(dir,name,diagonal?"!@x "+sign+"out(x)->(@y ("+sign+"tail(y)&&"+sign+"extra(y)));":"!@x "+sign+"out(x)->((@y "+sign+"tail(y))&&(@z "+sign+"extra(z)));");names.add(name);}
        if(mode==1||mode>=3){ContextAuthorityChain.create(dir,"DenyTail","!"+(negative?"":"~")+(mode==5?"tail(9);":"tail(1);"));names.add("DenyTail");}if(mode>=2){ContextAuthorityChain.create(dir,"DenyExtra","!"+(negative?"":"~")+(mode==4?"extra(1);":"extra(2);"));names.add("DenyExtra");}if(reverse)Collections.reverse(names);
        String text="!@x "+sign+"q(x)&&~p1(x)->"+sign+"out(x);";boolean conflict=mode>=1;Set<String> origins;List<RevisionRef> pins;long settled;
        try(ContextSevenPremiseNativeWriteRunner.Fixture f=new ContextSevenPremiseNativeWriteRunner.Fixture(dir,"X")){
            require(f.root.compile("!~p1(1);",null,false),"original premise");for(String name:names)f.db.connectContext(name);f.db.saveConnections(f.root);ContextProductionInventory before=ContextSevenPremiseNativeWriteRunner.inventory(f);Set<String> initialOrigins=ContextSevenPremiseNativeWriteRunner.origins(before);long revision=f.db.getRevision();int rules=f.root.getRules().size();pins=ContextSevenPremiseNativeWriteRunner.pins(f);require(initialOrigins.size()==1&&pins.size()==names.size(),"only original premise and exact saved topology");
            ContextUniversalCandidate.Evaluation diagnostic=inspect(f,text,16);require(diagnostic.status==(conflict?Status.COLLISION:Status.CONSISTENT),"disjunction mode"+mode+": "+diagnostic.reason);Expected expected=new Expected(diagnostic.artifact,negative,diagonal,mode);
            Entry candidate=diagnostic.artifact.staged.primary.stream().filter(e->e.source.equals(diagnostic.artifact.candidate)).findFirst().get();require(candidate.clauses.size()==1&&candidate.clauses.get(0).variables.size()==1&&candidate.clauses.get(0).literals.size()==3,"whole unary universally quantified candidate");
            if(conflict)collision(diagnostic.qualification,expected,true);else consistent(diagnostic.qualification,expected,mode);barriers(diagnostic.artifact,expected);
            ContextUniversalCandidate.Evaluation stopped=inspect(f,text,1);require(stopped.status==Status.INCOMPLETE&&stopped.qualification.collision==null&&stopped.qualification.certificate==null&&stopped.reason.contains("common round limit"),"round cap never exposes a partial verdict");require(f.db.getRevision()==revision&&f.root.getRules().size()==rules&&ContextSevenPremiseNativeWriteRunner.inventory(f).fingerprint.equals(before.fingerprint)&&ContextSevenPremiseNativeWriteRunner.pins(f).equals(pins),"diagnostics preserve exact physical state");
            if(nativePath){ContextPendingNativeWrite attempt=f.db.beginUniversalWrite(f.root,1000,16,16,16,65536,1000000,WORK,500000,WORK,WORK);try{ContextProductionCommitException failure=null;try{f.root.query(text,null,false);}catch(ContextProductionCommitException caught){failure=caught;}if(conflict){require(failure!=null&&failure.getErrorCode()==StorageLifecycleErrorCode.STORAGE_CONTEXT_CONFLICT&&failure.getFamilyAudit()!=null&&failure.getFamilyAudit().verified&&failure.getFamilyAudit().verdict!=diagnostic.qualification,"fresh native-child conflict independently audited");collision(failure.getFamilyAudit().verdict,expected,false);}else require(failure==null,"actual native disjunctive family accepted");}finally{f.db.endNativeWrite(attempt);}}
            else{DB.UniversalProductionWriteResult result=f.db.writeUniversalProductionCandidate(f.root,text,1000,16,16,16,65536,1000000,WORK,500000,WORK,WORK,false);require(result.status==(conflict?DB.ProductionWriteStatus.COLLISION:DB.ProductionWriteStatus.PUBLISHED),"fresh public writer settles mode"+mode+": "+result.status+" / "+result.trial.reason);require(result.trial!=diagnostic&&result.audit!=null&&result.audit.verified&&result.audit.evaluation==result.trial&&result.before.getRevision()==revision&&result.after.getRevision()==f.db.getRevision(),"fresh audit and exact physical revision references");Expected fresh=new Expected(result.trial.artifact,negative,diagonal,mode);if(conflict)collision(result.trial.qualification,fresh,true);else{require(result.audit.oppositions.isEmpty(),"compatible disjunction has no collision attribution");consistent(result.trial.qualification,fresh,mode);}}
            ContextProductionInventory after=ContextSevenPremiseNativeWriteRunner.inventory(f);origins=ContextSevenPremiseNativeWriteRunner.origins(after);settled=f.db.getRevision();require(ContextSevenPremiseNativeWriteRunner.pins(f).equals(pins),"exact saved pin order unchanged");if(conflict)require(settled==revision&&f.root.getRules().size()==rules&&after.fingerprint.equals(before.fingerprint)&&origins.equals(initialOrigins),"both-Deny refusal preserves exact original theory");else{require(settled>revision&&after.primary.size()==2&&origins.size()==2&&origins.containsAll(initialOrigins),"only one whole candidate published");ContextProductionNativeBinding.Result bound=ContextProductionNativeBinding.bind(f.root,after,WORK,500000);require(bound.bound&&bound.snapshot.primary.size()==2&&bound.snapshot.primary.stream().anyMatch(e->e.clauses.size()==1&&e.clauses.get(0).equivalent(candidate.clauses.get(0))),"actual published primary is exact requested rule");require(bound.snapshot.primary.stream().allMatch(e->e.clauses.size()==1&&(e.clauses.get(0).equivalent(candidate.clauses.get(0))||e.clauses.get(0).literals.size()==1&&e.clauses.get(0).literals.get(0).predicate.equals("p1")&&!e.clauses.get(0).literals.get(0).positive)),"no disjunct, private assertion or displaced p1 imported as primary");}
            System.out.println("QUANTIFIED_CONJUNCTION diagonal="+diagonal+" mode="+mode+" negative="+negative+" reverse="+reverse+" native="+nativePath+" barriers="+diagnostic.qualification.completedBarriers);
        }
        try(ContextSevenPremiseNativeWriteRunner.Fixture f=new ContextSevenPremiseNativeWriteRunner.Fixture(dir,"X")){ContextProductionInventory inv=ContextSevenPremiseNativeWriteRunner.inventory(f);require(f.db.getRevision()>=settled&&inv.primary.size()==(conflict?1:2)&&ContextSevenPremiseNativeWriteRunner.origins(inv).equals(origins)&&ContextSevenPremiseNativeWriteRunner.pins(f).equals(pins),"ordinary reopen retains exact source theory and topology");}
    }
    static void run(boolean negative,boolean reverse,boolean diagonal,String marker){try{for(int mode=0;mode<6;mode++)for(boolean nativePath:new boolean[]{false,true})one(negative,reverse,diagonal,mode,nativePath);System.out.println(marker+" checks="+(checks+ContextAuthorityChain.checks));System.exit(0);}catch(Throwable failure){failure.printStackTrace();System.exit(1);}}
}
